 indefinitely semi-protected biographies of living people', ['edit-full-all-blp-indef'] = 'Wikipedia indefinitely protected biographies of living people', ['edit-semi-all-all-indef'] = 'Wikipedia indefinitely semi-protected pages', ['move-full-talk-all-all'] = 'Wikipedia move-protected talk pages', ['move-full-all-all-indef'] = 'Wikipedia indefinitely move-protected pages', ['edit-semi-all-all-all'] = 'Wikipedia semi-protected pages', ['all-all-all-all-all'] = 'Wikipedia protected pages', ['edit-semi-category-all-all'] = 'Wikipedia semi-protected categories', ['edit-full-all-all-all'] = 'Wikipedia protected categories', ['move-full-all-all-all'] = 'Wikipedia move-protected pages', ['all-all-all-office-all'] = 'Wikipedia Office-protected pages', ['pc-semi-all-all-all'] = 'Wikipedia pending changes protected pages (level 1)', ['pc-reviewer-all-all-all'] = 'Wikipedia pending changes protected pages (level 2)', }
local nskeys = { [2] = 'user', [3] = 'user', [4] = 'project', [6] = 'file', [10] = 'template', [12] = 'project', [14] = 'category', [100] = 'portal', }
local error_categories = { incorrect = 'Wikipedia pages with incorrect protection templates', no_expiry = 'Wikipedia protected pages without expiry', create = 'Wikipedia pages tagged as create-protected', template = 'Wikipedia template-protected pages other than templates and modules' }
local template_types = { vandalism = { namespaces = false, -- defaults to all namespaces editLevels = false, -- all edit protection levels moveLevels = false, -- all move protection levels createLevels = false, -- all create protection levels header = false, reason = 'due to [[Wikipedia:Vandalism|vandalism]]', icon_reason = 'due to vandalism', } }
-------------------------------------------------------------------------------- -- Main functions --------------------------------------------------------------------------------
local getArgs = require('Module:Arguments').getArgs local yesno = require('Module:Yesno')
local p = {}
function p.main(frame) -- Get data local args = getArgs(frame) local title = p.getTitle(args.page) local protType, protLevel = p.getProtectionStatus(title) local namespace = p.getNamespace(title) local expiry = p.getExpiry(args.expiry) local reason = p.getReason(args.reason)
-- Sort categories and build a category link with the best match categories = p.sortCategories(categories, protType, protLevel, namespace, expiry, reason) local category = categories[1].name category = string.format('[[Category:%s]]', category)
-- Find whether we are small or not and output a padlock or a banner as appropriate local isSmall = yesno(args.small, true) if isSmall then return p.exportPadlock() else return p.exportBanner() end end
function p.parseNamespace(ns) -- The ns variable is the namespace number. if not ns or type(ns) ~= 'number' then return 'all' end local nskey = nskeys[ns] if not nskey and ns % 2 == 1 then nskey = 'talk' elseif not nskey then nskey = 'all' end return nskey end
function p.getCategoryName(cats, protType, protLevel, namespace, reason, expiry) -- Preprocess parameters cats = cats or categories protType = protType or 'all' protLevel = protLevel or 'all' namespace = p.parseNamespace(namespace) reason = reason or 'all' if not expiry then expiry = 'all' elseif expiry ~= 'indef' then expiry = 'temp' end
-- Define the key table and the order to test it in local keyTable = {protType, protLevel, namespace, reason, expiry} local tryOrder = {5, 3, 4, 2, 1}
-- Try successively generic matches until we run out of key combinations local function attemptMatch() local key = table.concat(keyTable, '-') return cats[key] end local attempt = attemptMatch() if attempt then return attempt end for i, keyTableKey in ipairs(tryOrder) do keyTable[keyTableKey] = 'all' attempt = attemptMatch() if attempt then return attempt end end error('No category match found; please define the category for key "all-all-all-all-all"') end
return p

