ges protected from banned users', ['edit-autoconfirmed-all-blp-temp'] = 'Wikipedia temporarily semi-protected biographies of living people', ['edit-sysop-all-blp-temp'] = 'Wikipedia temporarily protected biographies of living people', ['edit-autoconfirmed-all-blp-all'] = 'Wikipedia indefinitely semi-protected biographies of living people', ['edit-sysop-all-blp-all'] = 'Wikipedia indefinitely protected biographies of living people', ['edit-autoconfirmed-all-all-indef'] = 'Wikipedia indefinitely semi-protected pages', ['edit-autoconfirmed-category-all-all'] = 'Wikipedia semi-protected categories', ['edit-sysop-category-all-all'] = 'Wikipedia protected categories', ['move-sysop-talk-all-all'] = 'Wikipedia move-protected talk pages', ['move-sysop-all-all-indef'] = 'Wikipedia indefinitely move-protected pages', ['edit-autoconfirmed-all-all-all'] = 'Wikipedia semi-protected pages', ['move-sysop-all-all-all'] = 'Wikipedia move-protected pages', ['pc-autoconfirmed-all-all-all'] = 'Wikipedia pending changes protected pages (level 1)', ['pc-reviewer-all-all-all'] = 'Wikipedia pending changes protected pages (level 2)', ['all-all-all-office-all'] = 'Wikipedia Office-protected pages', ['all-all-all-all-all'] = 'Wikipedia protected pages', }
