cfg.images = { full = 'Padlock.svg', semi = 'Padlock-silver.svg', template = 'Padlock-pink.svg', pc1 = 'Padlock-silver-light.svg', pc2 = 'Padlock-orange.svg', move = 'Padlock-olive.svg', indef = 'Padlock-red.svg', office = 'Padlock-black.svg', create = 'Padlock-skyblue.svg' }
cfg.categories = { -- The key strings follow this format: -- type, level, ns, reason, expiry ['all-all-all-all-all'] = 'Wikipedia protected pages', ['all-all-all-office-all'] = 'Wikipedia Office-protected pages', ['edit-all-template-all-all'] = 'Wikipedia protected templates', ['edit-autoconfirmed-all-all-all'] = 'Wikipedia semi-protected pages', ['edit-autoconfirmed-all-all-indef'] = 'Wikipedia indefinitely semi-protected pages', ['edit-autoconfirmed-all-blp-all'] = 'Wikipedia indefinitely semi-protected biographies of living people', ['edit-autoconfirmed-all-blp-temp'] = 'Wikipedia temporarily semi-protected biographies of living people', ['edit-autoconfirmed-all-dispute-all'] = 'Wikipedia pages semi-protected due to dispute', ['edit-autoconfirmed-all-sock-all'] = 'Wikipedia pages semi-protected from banned users', ['edit-autoconfirmed-all-vandalism-all'] = 'Wikipedia pages semi-protected against vandalism', ['edit-autoconfirmed-category-all-all'] = 'Wikipedia semi-protected categories', ['edit-autoconfirmed-file-all-all'] = 'Semi-protected images', ['edit-autoconfirmed-portal-all-all'] = 'Semi-protected portals', ['edit-autoconfirmed-project-all-all'] = 'Semi-protected project pages', ['edit-autoconfirmed-talk-all-all'] = 'Semi-protected talk pages', ['edit-autoconfirmed-template-all-all'] = 'Wikipedia semi-protected templates', ['edit-autoconfirmed-template-all-all'] = 'Wikipedia semi-protected templates', ['edit-autoconfirmed-user-all-all'] = 'Wikipedia semi-protected user and user talk pages', ['edit-sysop-all-blp-all'] = 'Wikipedia indefinitely protected biographies of living people', ['edit-sysop-all-blp-temp'] = 'Wikipedia temporarily protected biographies of living people', ['edit-sysop-all-dispute-all'] = 'Wikipedia pages protected due to dispute', ['edit-sysop-all-sock-all'] = 'Wikipedia pages protected from banned users', ['edit-sysop-all-vandalism-all'] = 'Wikipedia pages protected against vandalism', ['edit-sysop-category-all-all'] = 'Wikipedia protected categories', ['edit-sysop-file-all-all'] = 'Protected images', ['edit-sysop-project-all-all'] = 'Protected project pages', ['edit-sysop-talk-all-all'] = 'Protected talk pages', ['edit-sysop-template-all-all'] = 'Wikipedia protected templates', ['edit-sysop-user-all-all'] = 'Wikipedia protected user and user talk pages', ['move-sysop-all-all-all'] = 'Wikipedia move-protected pages', ['move-sysop-all-all-indef'] = 'Wikipedia indefinitely move-protected pages', ['move-sysop-all-dispute-all'] = 'Wikipedia pages move-protected due to dispute', ['move-sysop-all-vandalism-all'] = 'Wikipedia pages move-protected due to vandalism', ['move-sysop-portal-all-all'] = 'Wikipedia move-protected portals', ['move-sysop-portal-all-all'] = 'Wikipedia move-protected portals', ['move-sysop-project-all-all'] = 'Wikipedia move-protected project pages', ['move-sysop-talk-all-all'] = 'Wikipedia move-protected talk pages', ['move-sysop-template-all-all'] = 'Wikipedia move-protected templates', ['move-sysop-user-all-all'] = 'Wikipedia move-protected user and user talk pages', ['autoreview-autoconfirmed-all-all-all'] = 'Wikipedia pending changes protected pages (level 1)', ['autoreview-reviewer-all-all-all'] = 'Wikipedia pending changes protected pages (level 2)', }
cfg.categoryNamespaces = { [2] = 'user', [3] = 'user', [4] = 'project', [6] = 'file', [10] = 'template', [12] = 'project', [14] = 'category', [100] = 'portal', }
cfg.pagetypeNamespaces = { [0] = 'article', [6] = 'file', [10] = 'template', [14] = 'category', [828] = 'module', default = 'page' }
