local getArgs = require('Module:Arguments').getArgs local yesno = require('Module:Yesno')
local p = {}
function p.main(frame) -- Get data local args = getArgs(frame) local title = p.getTitle(args.page) local protType, protLevel = p.getProtectionStatus(title) local namespace = p.getNamespace(title) local expiry = p.getExpiry(args.expiry) local reason = p.getReason(args.reason)
-- Sort categories and build a category link with the best match categories = p.sortCategories(categories, protType, protLevel, namespace, expiry, reason) local category = categories[1].name category = string.format('[[Category:%s]]', category)
-- Find whether we are small or not and output a padlock or a banner as appropriate local isSmall = yesno(args.small, true) if isSmall then return p.exportPadlock() else return p.exportBanner() end end
function p.parseNamespace(ns) -- The ns variable is the namespace number. if not ns or type(ns) ~= 'number' then return 'all' end local nskey = nskeys[ns] if not nskey and ns % 2 == 1 then nskey = 'talk' elseif not nskey then nskey = 'all' end return nskey end
function p.matchCategory(cats, protType, protLevel, namespace, reason, expiry) -- Preprocess parameters cats = cats or categories protType = protType or 'all' protLevel = protLevel or 'all' namespace = p.parseNamespace(namespace) reason = reason or 'all' if not expiry then expiry = 'all' elseif expiry ~= 'indef' then expiry = 'temp' end
-- Define the key table and the order to test it in local keyTable = {protType, protLevel, namespace, reason, expiry} local tryOrder = {5, 4, 3, 2, 1}
-- Try successively generic matches until we run out of key combinations local function attemptMatch() local key = table.concat(keyTable, '-') mw.log(key) -- for debugging return cats[key] end local attempt = attemptMatch() if attempt then return attempt end for i, keyTableKey in ipairs(tryOrder) do keyTable[keyTableKey] = 'all' attempt = attemptMatch() if attempt then return attempt end end error('No category match found; please define the category for key "all-all-all-all-all"') end
return p

