-- Define the key table and the order to test it in local keyTable = {protType, protLevel, namespace, reason, expiry} local attemptOrder = { {true, true, true, true, true}, {true, true, true, true, false}, {true, true, true, false, true}, {true, true, false, true, true}, {true, true, true, false, false}, {true, true, false, true, false}, {true, true, false, false, true}, {true, true, false, false, false}, {true, false, false, false, false}, {false, false, false, false, false} }
-- Try successively generic matches until we run out of key combinations for i, t in ipairs(attemptOrder) do local key = {} for j = 1, 5 do if t[j] then key[j] = keyTable[j] else key[j] = 'all' end end key = table.concat(key, '-') local attempt = cats[key] if attempt then return attempt end end error('No category match found; please define the category for key "all-all-all-all-all"') end
