rily protected biographies of living people', ['edit-semi-all-blp-indef'] = 'Wikipedia indefinitely semi-protected biographies of living people', ['edit-full-all-blp-indef'] = 'Wikipedia indefinitely protected biographies of living people', ['edit-semi-all-all-indef'] = 'Wikipedia indefinitely semi-protected pages', ['move-full-talk-all-all'] = 'Wikipedia move-protected talk pages', ['move-full-all-all-indef'] = 'Wikipedia indefinitely move-protected pages', ['edit-semi-all-all-all'] = 'Wikipedia semi-protected pages', ['all-all-all-all-all'] = 'Wikipedia protected pages', ['edit-semi-category-all-all'] = 'Wikipedia semi-protected categories', ['edit-full-category-all-all'] = 'Wikipedia protected categories', ['move-full-all-all-all'] = 'Wikipedia move-protected pages', ['all-all-all-office-all'] = 'Wikipedia Office-protected pages', ['pc-semi-all-all-all'] = 'Wikipedia pending changes protected pages (level 1)', ['pc-reviewer-all-all-all'] = 'Wikipedia pending changes protected pages (level 2)', }
