local getArgs = require('Module:Arguments').getArgs local yesno = require('Module:Yesno')
local p = {}
function p.main(frame) -- Get data local args = getArgs(frame) local title = p.getTitle(args.page) local protType, protLevel = p.getProtectionStatus(title) local namespace = p.getNamespace(title) local expiry = p.getExpiry(args.expiry) local reason = p.getReason(args.reason)
-- Sort categories and build a category link with the best match categories = p.sortCategories(categories, protType, protLevel, namespace, expiry, reason) local category = categories[1].name category = string.format('[[Category:%s]]', category)
-- Find whether we are small or not and output a padlock or a banner as appropriate local isSmall = yesno(args.small, true) if isSmall then return p.exportPadlock() else return p.exportBanner() end end
function p.parseNamespace(ns) -- The ns variable is the namespace number. if not ns or type(ns) ~= 'number' then return 'all' end local nskey = nskeys[ns] if not nskey and ns % 2 == 1 then nskey = 'talk' elseif not nskey then nskey = 'all' end return nskey end
function p.getCategoryName(cats, protType, protLevel, namespace, reason, expiry) -- Preprocess parameters cats = cats or categories protType = protType or 'all' protLevel = protLevel or 'all' namespace = p.parseNamespace(namespace) reason = reason or 'all' if not expiry then expiry = 'all' elseif expiry ~= 'indef' then expiry = 'temp' end
-- Define the key table and the order to test it in. -- This part is a little like playing regex golf - we have to make up a new -- rule for every idiosyncracy that was in the old template system. local keyTable = {protType, protLevel, namespace, reason, expiry} local attemptOrder = { -- type, level, ns, reason, expiry {true, true, true, true, true}, -- 1 {true, true, true, true, false}, -- 2 {true, true, true, false, true}, -- 3 {true, true, false, true, true}, -- 4 {true, true, true, false, false}, -- 5 {true, true, false, true, false}, -- 6 {true, true, false, false, true}, -- 7 {true, true, false, false, false}, -- 8 {true, false, true, false, false}, -- 9 {true, false, false, false, false}, -- 10 {false, false, false, false, false} -- 11 } if reason ~= 'vandalism' then attemptOrder[3], attemptOrder[4] = attemptOrder[4], attemptOrder[3] attemptOrder[5], attemptOrder[6] = attemptOrder[6], attemptOrder[5] end
-- Try successively generic matches until we run out of key combinations for i, t in ipairs(attemptOrder) do local key = {} for j, useKeyTable in ipairs(t) do if useKeyTable then key[j] = keyTable[j] else key[j] = 'all' end end key = table.concat(key, '-') mw.log(key) -- for debugging local attempt = cats[key] if attempt then return attempt end end error('No category match found; please define the category for key "all-all-all-all-all"') end
return p

