function p.parseNamespace(ns) -- The ns variable is the namespace number. if not ns or type(ns) ~= 'number' then return 'all' end local nskey = nskeys[ns] if not nskey and ns % 2 == 1 then nskey = 'talk' elseif not nskey then nskey = 'all' end return nskey end
function p.getCategoryName(cats, protType, protLevel, namespace, reason, expiry) -- Preprocess parameters cats = cats or categories protType = protType or 'all' protLevel = protLevel or 'all' namespace = p.parseNamespace(namespace) reason = reason or 'all' if not expiry then expiry = 'all' elseif expiry ~= 'indef' then expiry = 'temp' end
-- Define the key table and the order to test it in. -- This part is a little like playing regex golf - we have to make up a new -- rule for every idiosyncracy that was in the old template system. local keyTable = {protType, protLevel, namespace, reason, expiry} local attemptOrder = { -- type, level, ns, reason, expiry {true, true, true, true, true}, -- 1 {true, true, true, true, false}, -- 2 {true, true, false, true, true}, -- 3 {true, true, true, false, true}, -- 4 {true, true, false, true, false}, -- 5 {true, true, true, false, false}, -- 6 {true, true, false, false, true}, -- 7 {true, false, true, true, true}, -- 8 {true, false, true, true, false}, -- 9 {true, false, false, true, true}, -- 10 {true, false, true, false, true}, -- 11 {true, false, false, true, false}, -- 12 {true, false, true, false, false}, -- 13 {true, false, false, false, true}, -- 14 {true, false, false, false, false}, -- 15 {false, false, false, false, false} -- 16 }
local reasonBehaviors = { vandalism = 'namespaceFirst', dispute = 'reasonFirst', blp = 'reasonFirst', sock = 'reasonFirst', office = 'reasonOnly', }
local reasonBehavior = reasonBehaviors[reason] if reasonBehavior == 'reasonOnly' then local attempt = cats[reason] if attempt then return attempt else error('the category for key "' .. reason .. '" is undefined') end elseif reasonBehavior == 'namespaceFirst' then -- Sort the order so that namespace keys are checked before reason matches. attemptOrder[3], attemptOrder[4] = attemptOrder[4], attemptOrder[3] attemptOrder[5], attemptOrder[6] = attemptOrder[6], attemptOrder[5] elseif reasonBehavior ~= 'reasonFirst' and reason ~= 'all' then error(reason .. ' is not a valid reason') end
-- Try successively generic matches until we run out of key combinations for i, t in ipairs(attemptOrder) do local key = {} for j, useKeyTable in ipairs(t) do if useKeyTable then key[j] = keyTable[j] else key[j] = 'all' end end key = table.concat(key, '-') mw.log(key) -- for debugging local attempt = cats[key] if attempt then return attempt end end error('No category match found; please define the category for key "all-all-all-all-all"') end
return p

