ted categories', ['edit-sysop-file-all-all'] = 'Protected images', ['edit-sysop-project-all-all'] = 'Protected project pages', ['edit-sysop-talk-all-all'] = 'Protected talk pages', ['edit-sysop-template-all-all'] = 'Wikipedia protected templates', ['edit-sysop-user-all-all'] = 'Wikipedia protected user and user talk pages', ['move-sysop-all-all-all'] = 'Wikipedia move-protected pages', ['move-sysop-all-all-indef'] = 'Wikipedia indefinitely move-protected pages', ['move-sysop-all-dispute-all'] = 'Wikipedia pages move-protected due to dispute', ['move-sysop-all-vandalism-all'] = 'Wikipedia pages move-protected due to vandalism', ['move-sysop-portal-all-all'] = 'Wikipedia move-protected portals', ['move-sysop-portal-all-all'] = 'Wikipedia move-protected portals', ['move-sysop-project-all-all'] = 'Wikipedia move-protected project pages', ['move-sysop-talk-all-all'] = 'Wikipedia move-protected talk pages', ['move-sysop-template-all-all'] = 'Wikipedia move-protected templates', ['move-sysop-user-all-all'] = 'Wikipedia move-protected user and user talk pages', ['pc-autoconfirmed-all-all-all'] = 'Wikipedia pending changes protected pages (level 1)', ['pc-reviewer-all-all-all'] = 'Wikipedia pending changes protected pages (level 2)', }
